+                .await,
+            Err(CaseError::Invalid)
+        );
+        assert_eq!(
+            app.create_case(
+                &context(Principal::User),
+                &read_capabilities,
+                &CreateCaseCommand {
+                    command_id: id(32),
+                    case_id: id(33),
+                    input: input(),
+                }
+            )
+            .await,
+            Err(CaseError::Denied)
+        );
+        assert_eq!(
+            app.list_cases(&context(Principal::User), &write_capabilities)
+                .await,
+            Err(CaseError::Denied)
+        );
+        assert_eq!(ports.writes.load(Ordering::SeqCst), 0);
+    }
+}
