+  signature text;
+BEGIN
+  FOREACH signature IN ARRAY ARRAY[
+    'aso.case_actor_context(text)',
+    'aso.require_case(uuid,text)',
+    'aso.case_record_json(uuid)',
+    'aso.read_case(uuid)',
