+    'aso.transition_case_command(uuid,uuid,bigint,text)'
+  ] LOOP
+    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', signature);
+    EXECUTE format('ALTER FUNCTION %s OWNER TO aso_case_owner', signature);
+  END LOOP;
+END;
+$$;
